import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { RecentFile, RecentKind, RecentVia } from '../types'
import {
  cdTargets,
  diffSnapshots,
  parsePorcelainZ,
  baseName,
  fileUrl,
  LIMIT,
  pushRecent,
  relativeTo,
  shortPath,
  type Snapshot,
} from './lib'

const PANE = 'recent-files'
const TITLE = 'Recent files'
const MAX_ROOTS = 10
/** Width the docked pane asks for; a width the person drags to wins. */
const COLUMNS = 48

const files = atom({ plugin: 'recent-files', key: 'files' } as const, [])
const roots = atom({ plugin: 'recent-files', key: 'roots' } as const, [])

type $ = EngineInterface

/** Mirror of the session's state in `$.store`, so a reload that loses it can restore. */
const MIRROR = 'last-session'

type Mirror = { sessionId: string; files: RecentFile[]; roots: string[] }

const persist = async ($: $): Promise<void> => {
  const mirror: Mirror = {
    sessionId: await $.session.id(),
    files: [...(await read($, files))],
    roots: [...(await read($, roots))],
  }
  await $.store.set(MIRROR, mirror)
}

const isMirror = (value: unknown): value is Mirror =>
  typeof value === 'object' &&
  value !== null &&
  typeof (value as Mirror).sessionId === 'string' &&
  Array.isArray((value as Mirror).files) &&
  Array.isArray((value as Mirror).roots)

/** Puts back this session's list when the host's state came back empty. */
const restore = async ($: $): Promise<void> => {
  if ((await read($, files)).length > 0) return
  const saved = await $.store.get(MIRROR)
  if (!isMirror(saved) || saved.sessionId !== (await $.session.id())) return
  await update($, files, () => saved.files.slice(0, LIMIT))
  await update($, roots, list => (list.length > 0 ? list : saved.roots))
}

const record = async (
  $: $,
  path: string,
  kind: RecentKind,
  via: RecentVia,
  agentId: string | undefined,
): Promise<void> => {
  const entry: RecentFile = { path, kind, via, at: await $.clock.now(), agentId }
  await update($, files, list => pushRecent(list, entry))
  await persist($).catch(() => undefined)
}

/** The git top level of `dir`, or undefined outside a repo. */
const topLevel = async ($: $, dir: string): Promise<string | undefined> => {
  const { exitCode, stdout } = await $.process.run(['git', '-C', dir, 'rev-parse', '--show-toplevel'])

  return exitCode === 0 ? stdout.trim() : undefined
}

const learnRoot = async ($: $, dir: string): Promise<void> => {
  const root = await topLevel($, dir)
  if (root === undefined) return
  await update($, roots, list => [root, ...list.filter(one => one !== root)].slice(0, MAX_ROOTS))
  await persist($).catch(() => undefined)
}

const dirname = (path: string): string => path.replace(/\/[^/]*$/, '') || '/'

/** Dirty and untracked files of every known repo, with their stat. */
const snapshot = async ($: $, repoRoots: readonly string[]): Promise<Snapshot> => {
  const snap: Snapshot = new Map()
  for (const root of repoRoots) {
    // --no-optional-locks: status must not take index.lock, or a git command the
    // session runs at the same moment (a parallel Bash call) fails on the lock.
    // core.fsmonitor=false: a repo's local config must not make status run a program.
    const { exitCode, stdout } = await $.process.run([
      'git', '--no-optional-locks', '-c', 'core.fsmonitor=false',
      '-C', root, 'status', '--porcelain=v1', '-z', '-uall',
    ])
    if (exitCode !== 0) continue
    for (const { path, code } of parsePorcelainZ(root, stdout)) {
      const stat = await $.fs.stat(path).catch(() => undefined)
      snap.set(path, { code, mtimeMs: stat?.mtimeMs ?? -1, size: stat?.size ?? -1 })
    }
  }

  return snap
}

const isOk = (ran: { deny?: string; isError?: boolean }): boolean =>
  ran.deny === undefined && ran.isError !== true

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await restore($).catch(() => undefined)
    try {
      await $.command.register({
        name: 'recent-files',
        description: 'Show the files most recently created or edited in this session',
      })
      await learnRoot($, e.cwd)
    } catch {
      // The pane still works without the command or the cwd's repo.
    }
    void $.ui.open({ id: PANE, title: TITLE, columns: COLUMNS })

    return started
  })

  on('command.run', { command: 'recent-files' }, async $ => {
    await $.ui.open({ id: PANE, title: TITLE, columns: COLUMNS })

    return { text: 'Recent files pane opened.' }
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const existed = await $.fs.exists(e.file_path).catch(() => true)
    const ran = await next(e)
    if (isOk(ran)) {
      try {
        await record($, e.file_path, existed ? 'edited' : 'created', 'write', e.agentId)
        await learnRoot($, dirname(e.file_path))
      } catch {
        // Recording never gets in the way of the write itself.
      }
    }

    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const ran = await next(e)
    if (isOk(ran)) {
      try {
        await record($, e.file_path, 'edited', 'edit', e.agentId)
        await learnRoot($, dirname(e.file_path))
      } catch {
        // Recording never gets in the way of the edit itself.
      }
    }

    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'NotebookEdit' }, async ($, e, next) => {
    const ran = await next(e)
    if (isOk(ran)) {
      try {
        await record($, e.notebook_path, 'edited', 'notebook', e.agentId)
        await learnRoot($, dirname(e.notebook_path))
      } catch {
        // Recording never gets in the way of the edit itself.
      }
    }

    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    let watched: string[] = []
    let before: Snapshot | undefined
    try {
      for (const dir of cdTargets(e.command)) await learnRoot($, dir)
      watched = [...(await read($, roots))]
      before = await snapshot($, watched)
    } catch {
      before = undefined
    }

    const ran = await next(e)

    if (before !== undefined && watched.length > 0) {
      try {
        const after = await snapshot($, watched)
        for (const { path, kind } of diffSnapshots(before, after)) {
          await record($, path, kind, 'bash', e.agentId)
        }
      } catch {
        // A failed snapshot only means this command's writes go unlisted.
      }
    }

    return ran
  }).catch(($, e, next) => next(e))

  // A pane: docked at the right of a fullscreen transcript, inline above the
  // prompt otherwise. Each file shows its name only; the name is an OSC 8 link
  // to the file's absolute path, so a terminal that opens links (Orca) opens it,
  // while the pane stays narrow. The folder, relative to the session's working
  // directory, and what happened follow dim on the next line.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Link, Text } = $.ui.resolve(e)
    const list = await read($, files)
    const cwd = await $.session.cwd()

    return (
      <Box flexDirection="column">
        {list.length === 0 && <Text dimColor>No files created or edited yet.</Text>}
        {list.map(file => (
          <Box key={file.path} flexDirection="column" paddingX={1}>
            {file.kind === 'deleted' ? (
              <Text dimColor>{baseName(file.path)}</Text>
            ) : (
              <Link href={fileUrl(file.path)} label={baseName(file.path)} />
            )}
            <Text dimColor>
              {'  '}
              {shortPath(relativeTo(cwd, file.path.slice(0, file.path.length - baseName(file.path).length))) || './'}
              {' · '}
              {file.kind} · {file.via}
              {file.agentId === undefined ? '' : ' · subagent'} ·{' '}
              {new Date(file.at).toLocaleTimeString('ja-JP', { hour12: false, hour: '2-digit', minute: '2-digit' })}
            </Text>
          </Box>
        ))}
      </Box>
    )
  })
}

