import type { RecentFile, RecentKind } from '../types'

/** How many files the pane lists. */
export const LIMIT = 5

/** Puts `entry` first, drops any older entry for the same path, keeps LIMIT. */
export const pushRecent = (list: readonly RecentFile[], entry: RecentFile): RecentFile[] =>
  [entry, ...list.filter(one => one.path !== entry.path)].slice(0, LIMIT)

/** One path of `git status --porcelain=v1 -z -uall`, absolute, with its XY code. */
export type StatusEntry = { path: string; code: string }

/**
 * Parses `git status --porcelain=v1 -z -uall` output into absolute paths.
 * A rename or copy (`R`/`C`) carries the new path, then the old one as a
 * separate NUL-terminated field, which is skipped.
 */
export const parsePorcelainZ = (root: string, out: string): StatusEntry[] => {
  const fields = out.split('\0')
  const entries: StatusEntry[] = []
  for (let i = 0; i < fields.length; i += 1) {
    const field = fields[i]
    if (field === undefined || field.length < 4) continue
    const code = field.slice(0, 2)
    entries.push({ path: `${root}/${field.slice(3)}`, code })
    if (code[0] === 'R' || code[0] === 'C') i += 1
  }

  return entries
}

/** A file's state in a snapshot: its status code and what stat said. */
export type Signature = { code: string; mtimeMs: number; size: number }

export type Snapshot = Map<string, Signature>

/**
 * Compares two snapshots of the dirty and untracked files of the same repos
 * and says which files the command between them changed, and how.
 */
export const diffSnapshots = (
  before: Snapshot,
  after: Snapshot,
): { path: string; kind: RecentKind }[] => {
  const changed: { path: string; kind: RecentKind }[] = []
  for (const [path, now] of after) {
    const was = before.get(path)
    const isSame =
      was !== undefined &&
      was.code === now.code &&
      was.mtimeMs === now.mtimeMs &&
      was.size === now.size
    if (isSame) continue
    if (now.code.includes('D')) changed.push({ path, kind: 'deleted' })
    else if (was === undefined && (now.code === '??' || now.code.includes('A')))
      changed.push({ path, kind: 'created' })
    else changed.push({ path, kind: 'edited' })
  }
  for (const [path, was] of before) {
    if (after.has(path)) continue
    // Gone from the dirty set: an untracked file removed, or a change reverted.
    changed.push({ path, kind: was.code === '??' ? 'deleted' : 'edited' })
  }

  return changed
}

/** Absolute directories a command `cd`s into, so their repos can be watched. */
export const cdTargets = (command: string): string[] => {
  const found: string[] = []
  const pattern = /(?:^|[;&|(]\s*)cd\s+(["']?)(\/[^"'\s;&|)]+)\1/g
  for (const match of command.matchAll(pattern)) {
    if (match[2] !== undefined) found.push(match[2])
  }

  return found
}

/**
 * `path` relative to `cwd` when it lies under it (`src/a.ts`), else as is.
 * A terminal that links paths (Orca) resolves a relative one from the
 * session's working directory, and a short path stays on one line.
 */
export const relativeTo = (cwd: string, path: string): string => {
  const base = cwd.endsWith('/') ? cwd : `${cwd}/`

  return cwd !== '/' && path.startsWith(base) ? path.slice(base.length) : path
}

/** The last segment of a path: `/a/b/c.ts` → `c.ts`. */
export const baseName = (path: string): string => path.slice(path.lastIndexOf('/') + 1) || path

/**
 * A `file://` URL for an absolute path, each segment percent-encoded so
 * spaces, `#`, `?` and non-ASCII names survive (`/a b/c#1` → `file:///a%20b/c%231`).
 */
export const fileUrl = (path: string): string =>
  `file://${path.split('/').map(encodeURIComponent).join('/')}`

/** `/Users/name/x` → `~/x`, for display. */
export const shortPath = (path: string): string => path.replace(/^\/Users\/[^/]+(?=\/|$)/, '~')

