export type RecentKind = 'created' | 'edited' | 'deleted'

export type RecentVia = 'write' | 'edit' | 'notebook' | 'bash'

export type RecentFile = {
  path: string
  kind: RecentKind
  via: RecentVia
  at: number
  agentId?: string
}

declare module 'claude-code' {
  interface PluginState {
    'recent-files': { files: RecentFile[]; roots: string[] }
  }
}
